<section class="card"><div class="dashboard-card-heading"><h2>Attendance overview</h2><a href="{{ url('/attendance') }}">View records ↗</a></div><div class="dashboard-progress"><div class="dashboard-ring" style="--progress:{{ max(0,min(100,$summary['percentage']??0)) }}" role="img" aria-label="{{ $summary['percentage']===null?'No elapsed applicable attendance days':$summary['percentage'].' percent attendance' }}"><strong>{{ $summary['percentage']===null?'—':$summary['percentage'].'%' }}</strong></div><div><p>{{ $summary['numerator'] }} of {{ $summary['denominator'] }} days</p><small>Applicable elapsed<br>programme days</small></div></div><p class="dashboard-chart-note">{{ $summary['pending'] }} pending attendance {{ $summary['pending']===1?'record':'records' }}. Your attendance is separate from assessment completion.</p></section>
